-- V90.gl — Working Capital, Cash & Credit Management
CREATE TABLE IF NOT EXISTS erp_working_capital_snapshot(snapshot_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_key TEXT NOT NULL,cash_available NUMERIC NOT NULL DEFAULT 0,receivables NUMERIC NOT NULL DEFAULT 0,overdue_receivables NUMERIC NOT NULL DEFAULT 0,payables NUMERIC NOT NULL DEFAULT 0,overdue_payables NUMERIC NOT NULL DEFAULT 0,inventory_value NUMERIC NOT NULL DEFAULT 0,customer_credit_limit NUMERIC NOT NULL DEFAULT 0,customer_credit_used NUMERIC NOT NULL DEFAULT 0,collection_target NUMERIC NOT NULL DEFAULT 0,collections_received NUMERIC NOT NULL DEFAULT 0,payment_commitments NUMERIC NOT NULL DEFAULT 0,net_working_capital NUMERIC NOT NULL DEFAULT 0,credit_utilization_pct NUMERIC NOT NULL DEFAULT 0,collection_realization_pct NUMERIC NOT NULL DEFAULT 0,dso_days NUMERIC NOT NULL DEFAULT 0,dpo_days NUMERIC NOT NULL DEFAULT 0,inventory_days NUMERIC NOT NULL DEFAULT 0,cash_conversion_cycle_days NUMERIC NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,period_key));
CREATE INDEX IF NOT EXISTS ix_working_capital_scope ON erp_working_capital_snapshot(organization_id,entity_id,period_key);
